def _build_worker_context(project: str) -> str:
    """Assemble minimal execution environment context for a worker subprocess.

    Only includes server connection info (SSH, env, code path) — the bare
    minimum a Worker needs to run commands on the right machine.

    ARCHITECTURE.md / MODELS.md are NOT injected here. The calling Agent
    should pass relevant project knowledge via the ``context`` parameter
    of ``spawn_worker`` if the task needs it.

    Returns an empty string when no useful context can be assembled.
    """
    lines: list[str] = [
        "<project_context>",
        f"# 项目: {project}",
        "",
    ]
    has_content = False

    # --- Execution environment (server, SSH host, code path, env) ---
    try:
        from core.tools.project_config import load_project_config
        result = load_project_config(project)
        if result.success:
            cfg = result.data.get("config", {})
            exec_cfg = cfg.get("execution", {})
            # Handle both "server" (legacy) and "servers" (list) formats
            from core.tools.project_config import _parse_server_bindings
            bindings = _parse_server_bindings(exec_cfg)
            server_name = bindings[0]["server"] if bindings else ""
            account_name = bindings[0]["account"] if bindings else ""
            project_path = exec_cfg.get("project_path", "")

            env_lines: list[str] = []
            if server_name:
                # Only include server info if it's registered in resources
                try:
                    from core.tools.ssh import _load_resources, list_ssh_hosts
                    resources = _load_resources()
                    srv_cfg = resources.get("servers", {}).get(server_name, {})
                    if srv_cfg:
                        env_lines.append(f"- 服务器名: {server_name}")
                        if account_name:
                            env_lines.append(f"- SSH 账户: {account_name}（调用 ssh_execute / submit_training_job 时传入 account=\"{account_name}\"）")
                        host = srv_cfg.get("host", "")
                        env_activate = srv_cfg.get("env_activate", "")
                        if host:
                            ssh_target = host
                            try:
                                ssh_result = list_ssh_hosts()
                                if ssh_result.success:
                                    for h in ssh_result.data.get("hosts", []):
                                        if h.get("registered") and h.get("host_alias") == server_name:
                                            ssh_target = server_name
                                            break
                            except Exception:
                                pass
                            env_lines.append(
                                f"- SSH 连接命令: ssh {ssh_target}"
                                f"  # 必须用此命令，~/.ssh/config 自动应用密钥和跳板机，禁止用裸 IP"
                            )
                        if env_activate:
                            env_lines.append(f"- 环境激活命令: {env_activate}")
                    else:
                        logger.warning(
                            "[worker_context] server '%s' not found in resources, skipping",
                            server_name,
                        )
                except Exception:
                    pass
            if project_path:
                env_lines.append(f"- 项目代码根目录: {project_path}")

            if env_lines:
                lines.append("## 运行环境")
                lines.extend(env_lines)
                lines.append("")
                has_content = True
    except Exception:
        pass

    # --- Active constraints (Director-enforced rules Workers must obey) ---
    try:
        from core.tools.constraints import get_active_constraints_text
        constraints_text = get_active_constraints_text(project, scope="worker")
        if constraints_text:
            lines.append(constraints_text)
            has_content = True
    except Exception:
        pass
